// Pattern recogniser for the magic handoff marker convention. The same
// predicate runs in two places: the QEMU TCG plugin (C) and the vsim PC
// pre-scan (C++).
//
// The markers are RISC-V HINT instructions: SLTI with rd=x0 discards its
// result, so it is an architectural NOP on every conforming core. Marker
// binaries therefore run unmodified on real silicon and on every engine
// (fast/cycle/hybrid) -- unlike the retired `csrwi 0x7C0` markers, where
// CSR 0x7C0 is MILMB on Andes cores and the exit marker enabled ILM at
// base 0, killing standalone runs. The 12-bit immediate carries the
// marker kind; rs1 is pinned to x0 so each marker is one exact 32-bit
// word. SLTI has no compressed form, so markers are always 4 bytes.

#ifndef HYBRID_INSN_MATCH_H
#define HYBRID_INSN_MATCH_H

#include <stdbool.h>
#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef enum
{
  HYBRID_HANDOFF_NONE  = 0,
  HYBRID_HANDOFF_ENTER = 1,  // slti x0, x0, 0x5A0
  HYBRID_HANDOFF_EXIT  = 2,  // slti x0, x0, 0x5A1
} hybrid_handoff_kind;

// slti x0, x0, imm: OP-IMM (0x13), funct3=010, rd=rs1=x0, imm[31:20].
#define HYBRID_MARKER_ENTER_INSN 0x5A002013u
#define HYBRID_MARKER_EXIT_INSN  0x5A102013u

// Returns true when `insn` is one of the two marker HINTs. On match,
// *out_kind is set to ENTER or EXIT.
static inline bool hybrid_match_handoff_insn(uint32_t insn,
                                             hybrid_handoff_kind* out_kind)
{
  if (insn == HYBRID_MARKER_ENTER_INSN) {
    *out_kind = HYBRID_HANDOFF_ENTER;
    return true;
  }
  if (insn == HYBRID_MARKER_EXIT_INSN) {
    *out_kind = HYBRID_HANDOFF_EXIT;
    return true;
  }
  return false;
}

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_INSN_MATCH_H

// Translation-time capture of a handoff trigger insn. The QEMU TCG plugin
// allocates one of these per matched insn during vcpu_tb_trans and forwards
// the pointer as exec-callback userdata. compute_handoff_pc(site) returns
// the PC at which vsim should resume (i.e. the architectural PC immediately
// after the trigger insn retires).
//
// This indirection exists because qemu_plugin_read_register("pc") inside an
// exec callback returns a stale PC when V instructions retire just before
// the trigger -- TCG defers PC writes for performance and the gdbstub
// readback observes the lag. vaddr/size are deterministic at translate time
// (qemu_plugin_insn_vaddr/size), so vaddr+size is a lag-free post-trigger
// PC. Same predicate, two consumers: the plugin (C) and a doctest unit
// test (C++).
//
// Lifetime: sites are heap-allocated in vcpu_tb_trans and never freed --
// the plugin has no "TB invalidated" hook and trigger sites are bounded by
// the fixture's text (typically 1-2 marker insns).

#ifndef HYBRID_HANDOFF_SITE_H
#define HYBRID_HANDOFF_SITE_H

#include "hybrid/insn_match.h"

#include <stdint.h>

#ifdef __cplusplus
extern "C" {
#endif

typedef struct HandoffSite
{
  hybrid_handoff_kind kind;
  uint64_t            vaddr;
  uint32_t            size;
} HandoffSite;

static inline uint64_t compute_handoff_pc(const HandoffSite* site)
{
  return site->vaddr + (uint64_t) site->size;
}

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_HANDOFF_SITE_H

// Shared GDB register-name tables. Used by the QEMU TCG plugin (C) at
// drain time and by vsim's gdbstub handback client (C++) at restore
// time. The strings are the gdb wire contract for QEMU's RISC-V
// gdbstub - any reordering or renaming must be done in lock-step here.

#ifndef HYBRID_REG_NAMES_H
#define HYBRID_REG_NAMES_H

#ifdef __cplusplus
extern "C" {
#endif

// Index = x register index. Matches the names in QEMU's
// gdb-xml/riscv-64bit-cpu.xml (the wire contract for qemu_plugin_register
// lookup). NB: x8 is "fp", NOT "s0" -- QEMU's gdbstub uses the
// frame-pointer alias. Looking it up as "s0" yields a NULL handle and
// silently zeros gpr[8] in the drained state.
static const char *const hybrid_gpr_names[32] = {
    "zero", "ra",  "sp",  "gp",  "tp",  "t0", "t1", "t2",
    "fp",   "s1",  "a0",  "a1",  "a2",  "a3", "a4", "a5",
    "a6",   "a7",  "s2",  "s3",  "s4",  "s5", "s6", "s7",
    "s8",   "s9",  "s10", "s11", "t3",  "t4", "t5", "t6",
};

// Index = f register index. From riscv-64bit-fpu.xml.
static const char *const hybrid_fpr_names[32] = {
    "ft0", "ft1", "ft2",  "ft3",  "ft4", "ft5", "ft6", "ft7",
    "fs0", "fs1", "fa0",  "fa1",  "fa2", "fa3", "fa4", "fa5",
    "fa6", "fa7", "fs2",  "fs3",  "fs4", "fs5", "fs6", "fs7",
    "fs8", "fs9", "fs10", "fs11", "ft8", "ft9", "ft10","ft11",
};

#ifdef __cplusplus
}  // extern "C"
#endif

#endif  // HYBRID_REG_NAMES_H

